//! Excluded actual-gallery shared clock accepted-value reveal and user focus intent.
// Reuse the frozen whole gallery module and its actual shared controlled clocks.
use super::clock_composition_review::gallery_datetime;
use dioxus::prelude::*;
use dioxus_ix::*;

#[component]
pub fn ClockRevealPreview() -> Element {
    #[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
    let window = dioxus::desktop::window();
    rsx! {
        style { {STYLES} }
        style { {gallery_datetime::STYLES} }
        IxTheme { class:"clock-reveal-review",
            gallery_datetime::DateTimeExamples {}
            div { onmounted:move |_| {
                #[cfg(all(feature="desktop",not(target_arch="wasm32")))]
                {let window=window.clone();spawn(async move {
                    let query=crate::dom_query::eval(NATIVE_CLOCK_REVEAL_CHECK);let _=query.send("clockreveal");
                    match query.join::<serde_json::Value>().await {
                        Ok(value)if value["ok"]==true=>{println!("Dioxus native Clock reveal: {value}");window.close();}
                        value=>{eprintln!("Dioxus native Clock reveal failed: {value:?}");std::process::exit(1);}
                    }
                });spawn(async move {futures_timer::Delay::new(std::time::Duration::from_secs(40)).await;eprintln!("Clock reveal native replay timed out");std::process::exit(1);});}
            } }
        }
    }
}
const STYLES: &str = "body{margin:0}.clock-reveal-review{box-sizing:border-box;min-height:100vh;padding:24px}@media(max-width:600px){.clock-reveal-review{padding:16px}}";

#[cfg(all(feature = "desktop", not(target_arch = "wasm32")))]
